L.forEach(m=>{m.t[1]=w(m.t[1]);(m.s||[]).forEach(t=>{t[1]=w(t[1]);if(m.k==="x"&&t[4])t[4]=w(t[4])});(m.q||[]).forEach(q=>{q[1]=w(q[1]);if(q[4])q[4]=w(q[4]);[0,1,3,4].forEach(i=>{q[i]=c(q[i])})})});
LV[4]=L;
